findings.codeql_raw_query:
/**
 * @name Unsafe numpy load operations
 * @description numpy.load, numpy.loadtxt, numpy.genfromtxt with untrusted input could lead to file access vulnerabilities
 * @kind path-problem
 * @problem.severity error
 * @id py/numpy-unsafe-load
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module NumpyLoadConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("numpy").getMember(["load", "loadtxt", "genfromtxt"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module NumpyLoadFlow = TaintTracking::Global<NumpyLoadConfig>;
import NumpyLoadFlow::PathGraph

from NumpyLoadFlow::PathNode source, NumpyLoadFlow::PathNode sink
where NumpyLoadFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted input flows to numpy file loading function $@.", source.getNode(), "user input"

/**
 * @name File path injection in numpy file operations
 * @description User-controlled data flowing to file path arguments in numpy's load/save operations
 * @kind path-problem
 * @problem.severity high
 * @id py/file-path-injection
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FilePathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for numpy file operations that take file paths
    exists(DataFlow::CallCfgNode call |
      // numpy.load, numpy.save, numpy.savez, numpy.savetxt, numpy.loadtxt
      (
        call = API::moduleImport("numpy").getMember(["load", "save", "savez", "savez_compressed", "savetxt", "loadtxt"]).getACall() or
        call = API::moduleImport("numpy.lib.npyio").getMember(["load", "save", "savez", "savez_compressed", "savetxt", "loadtxt"]).getACall()
      ) and
      sink = call.getArg(0)  // First argument is usually the file path
    )
  }
}

module FilePathFlow = TaintTracking::Global<FilePathConfig>;
import FilePathFlow::PathGraph

from FilePathFlow::PathNode source, FilePathFlow::PathNode sink
where FilePathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File path injection from $@.", source.getNode(), "user input"
